mapper.select:
select count(*) from basket_match_data_dispute
where match_id = #{matchId} and dispute_type = #{disputeType}
  and dispute_status in ('PENDING','PROCESSING') and is_delete = 0

select d.id, d.dispute_no as disputeNo, d.match_id as matchId, m.match_no as matchNo,
       d.dispute_type as disputeType, d.dispute_status as disputeStatus,
       d.initiator_type as initiatorType, d.initiator_id as initiatorId,
       d.dispute_reason as disputeReason, d.create_time as createTime,
       d.handle_time as handleTime, d.handle_result as handleResult
from basket_match_data_dispute d
join basket_match m on m.id = d.match_id and m.is_delete = 0
where d.is_delete = 0
and m.season_id = #{seasonId}
and d.match_id = #{matchId}
and d.dispute_status = #{disputeStatus}
and d.dispute_type = #{disputeType}
order by d.create_time desc, d.id desc
